cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Fused scaled-dot-product-attention kernel (flash-attention style, online softmax)
// One block handles BLOCK_M query rows for a single (batch, head) pair.
// One warp handles one query row; lanes within the warp split the head-dim.
__global__ void fused_attn_kernel(
    const half_t* __restrict__ Qg,
    const half_t* __restrict__ Kg,
    const half_t* __restrict__ Vg,
    half_t* __restrict__ Og,
    int B, int H, int N, int D,
    float scale)
{
  extern __shared__ half_t smem[];
  half_t* sK = smem;
  half_t* sV = smem + D;
  half_t* sQ = smem + 2 * D;

  const int bh = blockIdx.y;      // 0 .. B*H-1
  const int b  = bh / H;
  const int h  = bh % H;
  const int64_t base = ((int64_t)b * H + h) * (int64_t)N * (int64_t)D;

  // Global tensor views for this (b,h) slice, shaped (N, D)
  auto mQ = make_tensor(make_gmem_ptr(Qg + base), make_shape(N, D), make_stride(D, 1));
  auto mK = make_tensor(make_gmem_ptr(Kg + base), make_shape(N, D), make_stride(D, 1));
  auto mV = make_tensor(make_gmem_ptr(Vg + base), make_shape(N, D), make_stride(D, 1));
  auto mO = make_tensor(make_gmem_ptr(Og + base), make_shape(N, D), make_stride(D, 1));

  const int tid  = threadIdx.x;
  const int warp = tid / 32;
  const int lane = tid % 32;
  const int BLOCK_M = blockDim.x / 32;

  const int i = blockIdx.x * BLOCK_M + warp;  // query row handled by this warp

  const int chunk = D / 32;      // number of head-dim elements handled by this lane
  constexpr int MAXC = 32;       // supports D up to 32*32 = 1024 (fits this workload)

  float acc[MAXC];

  const bool active = (i < N);
  // Cooperatively stage the Q tile for this block into shared memory (coalesced)
  {
    const int vecD = D / 8;
    float4* sQ4 = reinterpret_cast<float4*>(sQ);
    for (int r = 0; r < BLOCK_M; ++r) {
      int row = blockIdx.x * BLOCK_M + r;
      if (row < N) {
        const float4* Qrow4 = reinterpret_cast<const float4*>(Qg + base + (int64_t)row * D);
        for (int vidx = tid; vidx < vecD; vidx += blockDim.x) {
          sQ4[(size_t)r * vecD + vidx] = Qrow4[vidx];
        }
      }
    }
  }
  __syncthreads();
  if (active) {
    #pragma unroll
    for (int t = 0; t < MAXC; ++t) {
      if (t < chunk) {
        acc[t] = 0.0f;
      }
    }
  }

  float m = -INFINITY;
  float l = 0.0f;

  for (int j = 0; j < N; ++j) {
    // Cooperatively load K_j and V_j into shared memory (coalesced)
    {
      const half_t* Krow = Kg + base + (int64_t)j * D;
      const half_t* Vrow = Vg + base + (int64_t)j * D;
      const int vecD = D / 8; // 8 half elements (16 bytes) per float4
      const float4* Krow4 = reinterpret_cast<const float4*>(Krow);
      const float4* Vrow4 = reinterpret_cast<const float4*>(Vrow);
      float4* sK4 = reinterpret_cast<float4*>(sK);
      float4* sV4 = reinterpret_cast<float4*>(sV);
      for (int vidx = tid; vidx < vecD; vidx += blockDim.x) {
        sK4[vidx] = Krow4[vidx];
        sV4[vidx] = Vrow4[vidx];
      }
    }
    __syncthreads();

    if (active) {
      float partial = 0.0f;
      const half_t* sQrow = sQ + (size_t)warp * D;
      if ((chunk % 8) == 0) {
        const float4* sK4 = reinterpret_cast<const float4*>(sK);
        const float4* sQ4 = reinterpret_cast<const float4*>(sQrow);
        int vec_count = chunk / 8;
        #pragma unroll
        for (int v = 0; v < 4; ++v) {
          if (v < vec_count) {
            int g = v * 32 + lane;
            float4 kv = sK4[g];
            float4 qv = sQ4[g];
            const half_t* kh = reinterpret_cast<const half_t*>(&kv);
            const half_t* qh = reinterpret_cast<const half_t*>(&qv);
            #pragma unroll
            for (int k = 0; k < 8; ++k) {
              partial += float(qh[k]) * float(kh[k]);
            }
          }
        }
      } else {
        #pragma unroll
        for (int t = 0; t < MAXC; ++t) {
          if (t < chunk) {
            partial += float(sQrow[lane * chunk + t]) * float(sK[lane * chunk + t]);
          }
        }
      }
      // warp reduction over the 32 lanes
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1) {
        partial += __shfl_down_sync(0xffffffffu, partial, off);
      }
      partial = __shfl_sync(0xffffffffu, partial, 0);
      float score = partial * scale;
      float new_m = fmaxf(m, score);
      float correction = expf(m - new_m);
      float p = expf(score - new_m);
      l = l * correction + p;
      if ((chunk % 8) == 0) {
        const float4* sV4 = reinterpret_cast<const float4*>(sV);
        int vec_count = chunk / 8;
        #pragma unroll
        for (int v = 0; v < 4; ++v) {
          if (v < vec_count) {
            int g = v * 32 + lane;
            float4 vv = sV4[g];
            const half_t* vh = reinterpret_cast<const half_t*>(&vv);
            #pragma unroll
            for (int k = 0; k < 8; ++k) {
              acc[v * 8 + k] = acc[v * 8 + k] * correction + p * float(vh[k]);
            }
          }
        }
      } else {
        #pragma unroll
        for (int t = 0; t < MAXC; ++t) {
          if (t < chunk) {
            int d = lane * chunk + t;
            acc[t] = acc[t] * correction + p * float(sV[d]);
          }
        }
      }
      m = new_m;
    }
    __syncthreads();
  }

  if (active) {
    if ((chunk % 8) == 0) {
      float4* Orow4 = reinterpret_cast<float4*>(const_cast<half_t*>(Og) + base + (int64_t)i * D);
      int vec_count = chunk / 8;
      #pragma unroll
      for (int v = 0; v < 4; ++v) {
        if (v < vec_count) {
          int g = v * 32 + lane;
          float4 ov;
          half_t* oh = reinterpret_cast<half_t*>(&ov);
          #pragma unroll
          for (int k = 0; k < 8; ++k) {
            oh[k] = half_t(acc[v * 8 + k] / l);
          }
          Orow4[g] = ov;
        }
      }
    } else {
      #pragma unroll
      for (int t = 0; t < MAXC; ++t) {
        if (t < chunk) {
          int d = lane * chunk + t;
          mO(i, d) = half_t(acc[t] / l);
        }
      }
    }
  }
}

torch::Tensor fused_sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
  TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
              "Q,K,V must be float16");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q,K,V must be 4D [B,H,N,D]");

  auto Qc = Q.contiguous();
  auto Kc = K.contiguous();
  auto Vc = V.contiguous();

  int64_t B = Qc.size(0);
  int64_t H = Qc.size(1);
  int64_t N = Qc.size(2);
  int64_t D = Qc.size(3);

  TORCH_CHECK(Kc.size(0) == B && Kc.size(1) == H && Kc.size(2) == N && Kc.size(3) == D,
              "K shape must match Q");
  TORCH_CHECK(Vc.size(0) == B && Vc.size(1) == H && Vc.size(2) == N && Vc.size(3) == D,
              "V shape must match Q");

  constexpr int BLOCK_M = 16;
  TORCH_CHECK(N % BLOCK_M == 0, "sequence length must be divisible by BLOCK_M (32) for this kernel");
  TORCH_CHECK(D % 32 == 0 && D <= 1024, "head dim must be divisible by 32 and <= 1024");

  auto O = torch::empty_like(Qc);

  dim3 grid((unsigned)(N / BLOCK_M), (unsigned)(B * H));
  dim3 block((unsigned)(BLOCK_M * 32));
  size_t smem_bytes = (2 * (size_t)D + (size_t)BLOCK_M * (size_t)D) * sizeof(half_t);

  float scale = 1.0f / sqrtf((float)D);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  fused_attn_kernel<<<grid, block, smem_bytes, stream>>>(
      reinterpret_cast<const half_t*>(Qc.data_ptr<at::Half>()),
      reinterpret_cast<const half_t*>(Kc.data_ptr<at::Half>()),
      reinterpret_cast<const half_t*>(Vc.data_ptr<at::Half>()),
      reinterpret_cast<half_t*>(O.data_ptr<at::Half>()),
      (int)B, (int)H, (int)N, (int)D, scale);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "fused_attn_kernel launch failed: ", cudaGetErrorString(err));

  return O;
}
